CREATE TABLE IF NOT EXISTS bookkeeping_batch_item_receipts (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id), action_key TEXT NOT NULL, receipt_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(run_id,action_key));
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_item_receipts_no_update BEFORE UPDATE ON bookkeeping_batch_item_receipts BEGIN SELECT RAISE(ABORT, 'bookkeeping batch receipts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_item_receipts_no_delete BEFORE DELETE ON bookkeeping_batch_item_receipts BEGIN SELECT RAISE(ABORT, 'bookkeeping batch receipts are append-only'); END;
CREATE TABLE IF NOT EXISTS bookkeeping_batch_approval_policy (id INTEGER PRIMARY KEY CHECK(id=1), self_approval_allowed INTEGER NOT NULL DEFAULT 0 CHECK(self_approval_allowed IN (0,1)), configured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO bookkeeping_batch_approval_policy(id,self_approval_allowed) VALUES(1,0);
